class RoomCard extends StatelessWidget {const RoomCard({super.key,required this.room});final RoomModel room;@override Widget build(BuildContext context){final saved=Get.find<SavedRoomsController>();final auth=Get.find<AuthController>();return Card(clipBehavior:Clip.antiAlias,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[GestureDetector(onTap:()=>Get.toNamed(AppRoutes.roomDetails,arguments:room),child:CachedNetworkImage(imageUrl:room.imageUrl,height:170,width:double.infinity,fit:BoxFit.cover,placeholder:(c,u)=>const SizedBox(height:170,child:Center(child:CircularProgressIndicator())),errorWidget:(c,u,e)=>const SizedBox(height:170,child:Icon(Icons.hotel,size:48)))),Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(room.name,style:const TextStyle(fontSize:16,fontWeight:FontWeight.bold))),Obx(()=>IconButton(onPressed:(){if(!auth.isLoggedIn){Get.toNamed(AppRoutes.login);return;}saved.toggle(room);},icon:Icon(saved.isSaved(room.id)?Icons.favorite:Icons.favorite_border,color:AppColors.gold))) ]),Text('${room.location} • ${room.size}',style:const TextStyle(color:AppColors.muted)),const SizedBox(height:8),Row(children:[const Icon(Icons.star,color:AppColors.gold,size:18),Text(' ${room.rating}  •  ${room.category}'),const Spacer(),Text('₹${room.price}/night',style:const TextStyle(fontWeight:FontWeight.bold,color:AppColors.navy))]),const SizedBox(height:10),FilledButton.tonal(onPressed:()=>Get.toNamed(AppRoutes.roomDetails,arguments:room),child:const Text('View details'))]))]));}}
